"use client";
import { cn } from "@/lib/utils";
import type { IconAppearanceProps } from "@/registry/new-york/icon-picker/IconAppearance";
import { iconColorPresets } from "@/registry/new-york/picked-icon/icon-types";

export const IconColorFields = ({
  value,
  onChange,
  colorMode,
  presets = iconColorPresets,
}: IconAppearanceProps) => (
  <div className="flex flex-col gap-2">
    {(["foreground", "background"] as const)
      .filter((mode) => colorMode === "both" || colorMode === mode)
      .map((mode) => {
        const field = mode === "foreground" ? "color" : "background";
        const label = mode === "foreground" ? "Icon color" : "Background";
        return (
          <fieldset key={mode} className="flex min-w-0 flex-wrap gap-1">
            <legend className="mb-1 text-xs font-medium">{label}</legend>
            <button
              type="button"
              aria-label={`Reset ${label.toLowerCase()}`}
              title="Reset"
              className="size-6 cursor-pointer rounded-full border text-xs"
              onClick={() => {
                const next = { ...value };
                if (field === "color") {
                  delete next.color;
                } else {
                  delete next.background;
                }
                onChange(next);
              }}
            >
              ×
            </button>
            {presets.map((preset) => (
              <button
                type="button"
                key={preset.label}
                title={preset.label}
                aria-label={`${label}: ${preset.label}`}
                aria-pressed={value[field] === preset[field]}
                className={cn(
                  "size-6 cursor-pointer rounded-full border border-black/10 outline-offset-2 focus-visible:outline-2",
                  value[field] === preset[field] &&
                    "ring-foreground ring-offset-background ring-2 ring-offset-2"
                )}
                style={{ backgroundColor: preset[field] }}
                onClick={() => onChange({ ...value, [field]: preset[field] })}
              />
            ))}
            <label className="flex items-center gap-1 text-xs">
              <span className="sr-only">Custom</span>
              <input
                aria-label={`Custom ${label.toLowerCase()}`}
                title={`Custom ${label.toLowerCase()}`}
                type="color"
                className="size-6 cursor-pointer border-0 bg-transparent p-0"
                value={
                  value[field]?.match(/^#[0-9a-f]{6}$/iu)?.[0] ?? "#475569"
                }
                onChange={(event) =>
                  onChange({ ...value, [field]: event.target.value })
                }
              />
            </label>
          </fieldset>
        );
      })}
  </div>
);

"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";
import { PickedIcon } from "@/registry/new-york/picked-icon/PickedIcon";

const pageSize = 32;
export const IconGrid = ({
  icons,
  selected,
  onSelect,
}: {
  icons: string[];
  selected: string;
  onSelect: (name: string) => void;
}) => {
  const [page, setPage] = useState(0);
  const pages = Math.max(1, Math.ceil(icons.length / pageSize));
  return (
    <div className="flex min-h-0 flex-1 flex-col gap-1">
      <div className="grid min-h-0 flex-1 grid-cols-8 content-start gap-1 overflow-y-auto overscroll-contain">
        {icons.slice(page * pageSize, (page + 1) * pageSize).map((name) => (
          <button
            key={name}
            type="button"
            aria-label={name}
            title={name.slice(7)}
            aria-pressed={selected === name}
            onClick={() => onSelect(name)}
            className={cn(
              "hover:bg-muted flex h-8 cursor-pointer items-center justify-center rounded-lg focus-visible:outline-2",
              selected === name &&
                "bg-muted ring-foreground/30 ring-1 ring-inset"
            )}
          >
            <PickedIcon value={{ name }} size={30} />
          </button>
        ))}
      </div>
      <nav
        aria-label="Icon pages"
        className="text-muted-foreground flex h-6 shrink-0 items-center justify-between text-xs"
      >
        <button
          type="button"
          aria-label="Previous icon page"
          disabled={page === 0}
          onClick={() => setPage(page - 1)}
          className="hover:text-foreground cursor-pointer rounded px-1 focus-visible:outline-2 disabled:cursor-default disabled:opacity-30"
        >
          Previous
        </button>
        <output>
          {page + 1} / {pages} · {icons.length} icons
        </output>
        <button
          type="button"
          aria-label="Next icon page"
          disabled={page + 1 >= pages}
          onClick={() => setPage(page + 1)}
          className="hover:text-foreground cursor-pointer rounded px-1 focus-visible:outline-2 disabled:cursor-default disabled:opacity-30"
        >
          Next
        </button>
      </nav>
    </div>
  );
};

"use client";

import type { ReactNode } from "react";

import { Button } from "@/components/ui/button";
import type { IconPickerContentProps } from "@/registry/new-york/icon-picker/IconPickerContent";
import { IconPickerContent } from "@/registry/new-york/icon-picker/IconPickerContent";
import type { IconValue } from "@/registry/new-york/picked-icon/icon-types";
import { PickedIcon } from "@/registry/new-york/picked-icon/PickedIcon";
import { PickerPopover } from "@/registry/new-york/picker-popover/PickerPopover";

export interface IconPickerProps extends Omit<
  IconPickerContentProps,
  "onSelect"
> {
  onChange: (value: IconValue) => void;
  trigger?: ReactNode;
  disabled?: boolean;
  label?: string;
}
export const IconPicker = ({
  onChange,
  trigger,
  disabled,
  label = "Choose icon",
  ...props
}: IconPickerProps) => (
  <PickerPopover
    label={label}
    disabled={disabled}
    trigger={
      trigger ?? (
        <Button
          variant="outline"
          disabled={disabled}
          aria-label={label}
          className="size-10 cursor-pointer p-0 shadow-none"
        >
          <PickedIcon value={props.value ?? { name: "lucide:smile" }} />
        </Button>
      )
    }
  >
    {(close) => (
      <IconPickerContent
        {...props}
        onSelect={(value) => {
          onChange(value);
          close();
        }}
      />
    )}
  </PickerPopover>
);

"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";
import type { IconSearch } from "@/registry/new-york/icon-picker/icon-search";
import { searchIcons } from "@/registry/new-york/icon-picker/icon-search";
import type { IconAppearanceProps } from "@/registry/new-york/icon-picker/IconAppearance";
import { IconAppearance } from "@/registry/new-york/icon-picker/IconAppearance";
import { IconGrid } from "@/registry/new-york/icon-picker/IconGrid";
import { useIconSearch } from "@/registry/new-york/icon-picker/use-icon-search";
import type { IconValue } from "@/registry/new-york/picked-icon/icon-types";
import { PickedIcon } from "@/registry/new-york/picked-icon/PickedIcon";

export interface IconPickerContentProps extends Pick<
  IconAppearanceProps,
  "colorMode" | "presets" | "allowFrame"
> {
  value?: IconValue | undefined;
  onSelect: (value: IconValue) => void;
  search?: IconSearch | undefined;
}
export const IconPickerContent = ({
  value,
  onSelect,
  search = searchIcons,
  ...appearance
}: IconPickerContentProps) => {
  const [draft, setDraft] = useState<IconValue>(
    value ?? { name: "lucide:smile" }
  );
  const [query, setQuery] = useState("");
  const result = useIconSearch(query, ["lucide"], search);
  return (
    <div className="flex h-[440px] flex-col gap-3 p-3">
      <input
        aria-label="Search icons"
        placeholder="Search Lucide icons…"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        className="bg-muted/60 focus-visible:ring-ring h-9 w-full shrink-0 rounded-lg border border-transparent px-3 text-sm outline-none focus-visible:ring-2"
      />
      <div
        aria-label="Icons"
        aria-busy={result.loading}
        className="flex min-h-24 flex-1 flex-col"
      >
        {result.loading && (
          <output className="text-muted-foreground p-3 text-sm">
            Loading icons…
          </output>
        )}
        {result.error && (
          <div
            role="alert"
            className="flex items-center justify-between p-3 text-sm"
          >
            Icons could not load.
            <Button variant="ghost" onClick={result.handleRetry}>
              Retry
            </Button>
          </div>
        )}
        {!result.loading &&
          !result.error &&
          (result.icons.length ? (
            <IconGrid
              key={query}
              icons={result.icons}
              selected={draft.name}
              onSelect={(name) => setDraft({ ...draft, name })}
            />
          ) : (
            <output className="p-3 text-sm">No icons found.</output>
          ))}
      </div>
      <IconAppearance value={draft} onChange={setDraft} {...appearance} />
      <div className="flex shrink-0 items-center gap-2 border-t pt-3">
        <PickedIcon value={draft} size={32} />
        <span
          className="text-muted-foreground min-w-0 flex-1 truncate text-xs"
          title={draft.name}
        >
          {draft.name.slice(7)}
        </span>
        <Button
          size="sm"
          className="cursor-pointer shadow-none"
          onClick={() => onSelect(draft)}
        >
          Use icon
        </Button>
      </div>
    </div>
  );
};

"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";
import { IconColorFields } from "@/registry/new-york/icon-picker/IconColorFields";
import type {
  IconColorMode,
  IconColorPreset,
  IconFrame,
  IconValue,
} from "@/registry/new-york/picked-icon/icon-types";
import { iconColorPresets } from "@/registry/new-york/picked-icon/icon-types";

export interface IconAppearanceProps {
  value: IconValue;
  onChange: (value: IconValue) => void;
  colorMode?: IconColorMode | undefined;
  presets?: IconColorPreset[] | undefined;
  allowFrame?: boolean | undefined;
}
const frames: IconFrame[] = ["circle", "square", "rounded", "squircle"];
const radii = { circle: "50%", rounded: "22%", square: "0", squircle: "50%" };
export const IconAppearance = ({
  value,
  onChange,
  colorMode = "paired",
  presets = iconColorPresets,
  allowFrame = true,
}: IconAppearanceProps) => {
  const [custom, setCustom] = useState(false);
  return (
    <div className="flex flex-col gap-3">
      {colorMode === "paired" && (
        <fieldset>
          <legend className="sr-only">Color presets</legend>
          <div className="mb-2 flex items-center justify-between text-xs">
            <span className="font-medium">Colors</span>
            <button
              type="button"
              onClick={() => setCustom(!custom)}
              aria-pressed={custom}
              className="text-muted-foreground hover:text-foreground cursor-pointer rounded px-1 focus-visible:outline-2"
            >
              {custom ? "Presets" : "Custom / separate"}
            </button>
          </div>
          {!custom && (
            <div className="grid grid-cols-10 gap-1.5">
              {presets.map((preset) => (
                <button
                  key={preset.label}
                  type="button"
                  title={preset.label}
                  aria-label={`Color preset: ${preset.label}`}
                  aria-pressed={
                    value.color === preset.color &&
                    value.background === preset.background
                  }
                  className={cn(
                    "flex aspect-square cursor-pointer items-center justify-center rounded-full outline-offset-2 focus-visible:outline-2",
                    value.color === preset.color &&
                      value.background === preset.background &&
                      "ring-foreground ring-offset-background ring-1 ring-offset-2"
                  )}
                  style={{ backgroundColor: preset.background }}
                  onClick={() =>
                    onChange({
                      ...value,
                      background: preset.background,
                      color: preset.color,
                    })
                  }
                >
                  <span
                    className="size-2.5 rounded-full"
                    style={{ backgroundColor: preset.color }}
                  />
                </button>
              ))}
            </div>
          )}
        </fieldset>
      )}
      {(colorMode !== "paired" || custom) && (
        <IconColorFields
          value={value}
          onChange={onChange}
          colorMode={colorMode === "paired" ? "both" : colorMode}
          presets={presets}
        />
      )}
      {allowFrame && (
        <fieldset className="flex items-center gap-1">
          <legend className="sr-only">Shape</legend>
          <span className="mr-auto text-xs font-medium" aria-hidden="true">
            Shape
          </span>
          {frames.map((frame) => (
            <button
              key={frame}
              type="button"
              aria-label={frame}
              title={frame}
              aria-pressed={(value.frame ?? "rounded") === frame}
              className={cn(
                "hover:bg-muted flex size-8 cursor-pointer items-center justify-center rounded-md focus-visible:outline-2",
                (value.frame ?? "rounded") === frame &&
                  "bg-muted ring-border ring-1 ring-inset"
              )}
              onClick={() => onChange({ ...value, frame })}
            >
              <span
                aria-hidden="true"
                className={cn(
                  "size-4 border-[1.5px] border-current",
                  frame === "squircle" && "[corner-shape:squircle]"
                )}
                style={{ borderRadius: radii[frame] }}
              />
            </button>
          ))}
        </fieldset>
      )}
    </div>
  );
};

import { z } from "zod";

export interface IconSearchRequest {
  query: string;
  prefixes: string[];
  signal: AbortSignal;
}
export type IconSearch = (request: IconSearchRequest) => Promise<string[]>;
const catalogSchema = z.object({
  uncategorized: z.array(z.string().regex(/^[a-z0-9-]+$/u)),
});
let catalog: string[] | undefined;
export const searchIcons: IconSearch = async ({ query, signal }) => {
  if (!catalog) {
    const response = await fetch(
      "https://api.iconify.design/collection?prefix=lucide",
      { signal }
    );
    if (!response.ok) {
      throw new Error(`Icon catalog failed: ${response.status}`);
    }
    const result = catalogSchema.parse(await response.json());
    catalog = result.uncategorized.toSorted().map((name) => `lucide:${name}`);
  }
  const words = query.toLowerCase().trim().split(/\s+/u);
  return catalog.filter((name) =>
    words.every((word) => name.slice(7).includes(word))
  );
};

"use client";

import { useEffect, useState } from "react";

import type { IconSearch } from "@/registry/new-york/icon-picker/icon-search";

export const useIconSearch = (
  query: string,
  prefixes: string[],
  search: IconSearch
) => {
  const key = prefixes.join(",");
  const [retry, setRetry] = useState(0);
  const [result, setResult] = useState<{
    key: string;
    icons: string[];
    error: boolean;
  }>();
  const requestKey = `${key}:${query}:${retry}`;
  useEffect(() => {
    const controller = new AbortController();
    const run = async () => {
      try {
        const icons = await search({
          prefixes: key.split(","),
          query: query.trim(),
          signal: controller.signal,
        });
        if (!controller.signal.aborted) {
          setResult({ error: false, icons, key: requestKey });
        }
      } catch {
        if (!controller.signal.aborted) {
          setResult({ error: true, icons: [], key: requestKey });
        }
      }
    };
    const timer = setTimeout(() => {
      void run();
    }, 200);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, key, search, requestKey]);
  return {
    error: result?.key === requestKey && result.error,
    handleRetry: () => setRetry((value) => value + 1),
    icons: result?.key === requestKey ? result.icons : [],
    loading: result?.key !== requestKey,
  };
};

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
